/* ================= [KD] إشعار تثبيت التطبيق (PWA) أعلى الصفحة - JS: كتلة kPwa بعد سكربت القائمة العلوية ================= */
.kPwa{position:fixed;top:12px;left:50%;z-index:1000;display:flex;flex-wrap:wrap;align-items:center;gap:12px;width:min(560px,calc(100% - 20px));box-sizing:border-box;padding:14px 16px;background:var(--kSrB);color:var(--kSrC);border:1px solid var(--kSrL);border-top:3px solid var(--kAcc);border-radius:16px;box-shadow:0 18px 50px rgba(0,0,0,.22);transform:translate(-50%,calc(-100% - 30px));opacity:0;transition:transform .45s cubic-bezier(.2,.9,.25,1.1),opacity .3s;font-family:var(--fontB);direction:rtl}
.kPwa.on{transform:translate(-50%,0);opacity:1}
.kPwa[hidden]{display:none}
.kPwaI{flex:0 0 48px;width:48px;height:48px;border-radius:12px;background:#fff;box-shadow:0 2px 8px rgba(0,0,0,.12)}
.kPwaT{flex:1 1 200px;min-width:0;line-height:1.6}
.kPwaT b{display:block;font-size:15px;font-weight:700}
.kPwaT span{display:block;font-size:13px;opacity:.8}
.kPwaB{display:flex;gap:8px;flex:0 0 auto;margin-inline-start:auto}
.kPwaB button{height:38px;padding:0 16px;border-radius:50px;font:700 13.5px var(--fontB);cursor:pointer;transition:filter .2s,background .2s}
.kPwaY{border:0;background:var(--kAcc);color:#fff}
.kPwaY:hover{filter:brightness(1.08)}
.kPwaN{border:1px solid var(--kSrL);background:transparent;color:inherit}
.kPwaN:hover{background:color-mix(in srgb,var(--kAcc) 10%,transparent)}
.kPwaX{position:absolute;top:6px;inset-inline-end:6px;width:28px;height:28px;padding:0;border:0;border-radius:50%;background:transparent;color:inherit;opacity:.55;font-size:14px;line-height:28px;cursor:pointer}
.kPwaX:hover{opacity:1;background:color-mix(in srgb,var(--kAcc) 10%,transparent)}
.kPwaH{flex:1 1 100%;margin:0;padding:10px 12px;border-radius:12px;background:color-mix(in srgb,var(--kAcc) 9%,transparent);font-size:13px;line-height:1.8}
.kPwaH svg{width:16px;height:16px;vertical-align:-3px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.kPwa:has(.kPwaX) .kPwaT{padding-inline-end:18px}
@media (max-width:480px){.kPwa{top:8px;padding:12px}.kPwaB{flex:1 1 100%}.kPwaB button{flex:1}}
@media (prefers-reduced-motion:reduce){.kPwa{transition:opacity .2s}}

