/* ---------- [KD] إشعار تثبيت التطبيق (PWA): يظهر لكل زائر لم يثبت المدونة بعد ----------
   - Chrome و Edge و Samsung: زر «تثبيت» يفتح نافذة التثبيت مباشرة (beforeinstallprompt)
   - iPhone و iPad وباقي المتصفحات: زر «تثبيت» يعرض خطوات التثبيت من قائمة المتصفح
   - لا يظهر داخل التطبيق المثبت ولا في متصفحات التطبيقات (فيسبوك وإنستغرام) ولا في Firefox على الحاسوب
   - «ليس الآن» أو ✕ يخفيه 7 أيام، وبعد التثبيت لا يظهر أبدا ---------- */
(function(){
  var KEY='kPwaOff',DAYS=7,ua=navigator.userAgent||'',deferred=null,box=null,shown=false;
  function get(){try{return localStorage.getItem(KEY)}catch(e){return null}}
  function set(v){try{localStorage.setItem(KEY,v)}catch(e){}}
  var standalone=(window.matchMedia&&matchMedia('(display-mode: standalone)').matches)||navigator.standalone===true;
  var off=get();
  if(standalone||off==='installed'||(off&&Date.now()-(+off)<DAYS*864e5)) return;
  if(/FBAN|FBAV|Instagram|Line\/|; wv\)|MicroMessenger|Snapchat|TikTok/i.test(ua)) return;
  var iOS=/iPhone|iPad|iPod/.test(ua)||(/Macintosh/.test(ua)&&navigator.maxTouchPoints>1);
  var android=/Android/.test(ua), firefox=/Firefox|FxiOS/.test(ua);
  var macSafari=!iOS&&/Macintosh/.test(ua)&&/Version\/1[7-9]|Version\/[2-9]\d/.test(ua)&&/Safari/.test(ua)&&!/Chrome|Chromium|Edg\//.test(ua);
  var chromium=/Chrome|Chromium|Edg\/|SamsungBrowser|OPR\//.test(ua)&&!firefox;
  var share="<svg viewBox='0 0 24 24'><path d='M12 3v12M8 7l4-4 4 4'/><path d='M5 12v7a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-7'/></svg>";
  function help(){
    if(iOS) return "في Safari اضغط زر المشاركة "+share+" أسفل الشاشة، ثم اختر «إضافة إلى الشاشة الرئيسية» ثم «إضافة».";
    if(macSafari) return "من قائمة «ملف» في Safari اختر «إضافة إلى Dock».";
    if(android) return "افتح قائمة المتصفح ⋮ أعلى الشاشة، ثم اختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية».";
    return "اضغط أيقونة التثبيت في شريط العنوان، أو افتح قائمة المتصفح ⋮ ثم اختر «تثبيت أحمد القندوسي» أو «التطبيقات ثم تثبيت هذا الموقع كتطبيق».";
  }
  function close(remember){
    if(!box) return; box.classList.remove('on');
    setTimeout(function(){box&&(box.hidden=true)},450);
    if(remember) set(String(Date.now()));
  }
  function show(){
    if(shown) return; shown=true;
    box=document.createElement('div');
    box.className='kPwa'; box.id='kPwa'; box.setAttribute('role','dialog'); box.setAttribute('aria-live','polite'); box.setAttribute('aria-label','تثبيت التطبيق');
    box.innerHTML="<img class='kPwaI' src='https://cdn.jsdelivr.net/gh/elkandoussi1/elhaqiba@93c29045504c7c30272e1503d010975e42f69df9/pwa/icon-96.png' width='48' height='48' alt=''/>"
      +"<div class='kPwaT'><b>ثبّت تطبيق أحمد القندوسي</b><span>وصول أسرع إلى الدروس والأدوات من شاشتك الرئيسية، ويعمل كتطبيق على الهاتف والحاسوب.</span></div>"
      +"<div class='kPwaB'><button class='kPwaY' type='button'>تثبيت</button><button class='kPwaN' type='button'>ليس الآن</button></div>"
      +"<button class='kPwaX' type='button' aria-label='إغلاق'>✕</button>"
      +"<p class='kPwaH' hidden></p>";
    document.body.appendChild(box);
    box.querySelector('.kPwaN').onclick=function(){close(true)};
    box.querySelector('.kPwaX').onclick=function(){close(true)};
    box.querySelector('.kPwaY').onclick=function(){
      if(deferred){
        var d=deferred; deferred=null; d.prompt();
        d.userChoice&&d.userChoice.then(function(c){ if(c&&c.outcome==='accepted'){set('installed');close(false)} else close(true) });
      }else{
        var h=box.querySelector('.kPwaH'); h.innerHTML=help(); h.hidden=false; this.textContent='حسنا'; this.onclick=function(){close(true)};
      }
    };
    setTimeout(function(){box.classList.add('on')},30);
  }
  window.addEventListener('beforeinstallprompt',function(e){e.preventDefault();deferred=e;if(document.readyState==='complete')setTimeout(show,1500)});
  window.addEventListener('appinstalled',function(){set('installed');close(false)});
  function start(){
    setTimeout(function(){
      if(deferred||iOS||macSafari||android||chromium) show();
    },4000);
  }
  if(document.readyState==='complete') start(); else window.addEventListener('load',start);
})();
